CREATE DATABASE IF NOT EXISTS ai_usecase_db
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE ai_usecase_db;

CREATE TABLE IF NOT EXISTS use_cases (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(500),
  dept VARCHAR(255),
  payload JSON NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);
-- Seed data: 12 use cases analyzed from input_data/ Excel workbooks
-- (AI_Transformation_Plan_Prod_EE.xlsx + AI_Transformation_Plan_RD_CENTER.xlsx).
-- INSERT IGNORE so re-running this file never duplicates or overwrites rows
-- someone has already edited through the app.
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_1', 'AI Vision ตรวจสอบการเข้าประกบแม่พิมพ์ (Mold Clamping Safety) เครื่อง Compression/Injection', 'Production', '{"id": "uc_ee_1", "name": "AI Vision ตรวจสอบการเข้าประกบแม่พิมพ์ (Mold Clamping Safety) เครื่อง Compression/Injection", "dept": "Production", "owner": "ผจก.ส่วนผลิต Molding Plant", "problem": "ขั้นตอนขึ้นรูป (ทั้งเครื่อง Compression และ Injection) พนักงานกด Start ให้เครื่องทำงานอัตโนมัติ แล้วต้องเฝ้าดูการเข้าประกบของแม่พิมพ์ด้วยสายตาเพื่อความปลอดภัย หากตรวจไม่ทันหรือพลาด อาจทำให้แม่พิมพ์เสียหายหรือเกิดอุบัติเหตุ ผลลัพธ์ขึ้นกับความชำนาญของพนักงานแต่ละคนและไม่มีการบันทึกหลักฐานย้อนหลัง", "solution": "พนักงานเฝ้าดูด้วยตาเปล่าและกดหยุดเครื่องเองเมื่อสังเกตความผิดปกติ ไม่มีระบบแจ้งเตือนหรือบันทึกอัตโนมัติ อ้างอิงตาม WI-A07-001 (การ SET UP และทวนสอบกระบวนการก่อนการผลิต)", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 2.3)", "aiType": "vision", "hardware": "กล้อง Industrial + Edge GPU ติดตั้งหน้าเครื่องขึ้นรูปทุกเครื่อง ร่วมกับเซนเซอร์วัดแรงดัน (Pressure Sensor)", "impact": 4, "feasibility": 3, "data": 2, "risk": 3, "risks": "ต้องเก็บวิดีโอการเคลื่อนที่ของแม่พิมพ์ทั้งสภาวะปกติ/ผิดปกติให้เพียงพอสำหรับเทรนโมเดล และมีความเสี่ยงด้านความปลอดภัยหากระบบแจ้งเตือนผิดพลาด (false negative) จึงต้องมีมาตรการ Fail-safe ควบคู่กับคนเสมอ", "resources": "ทีม AI Dev 2 คน + ทีม Automation/Eng., ระยะเวลา 12 สัปดาห์, งบประมาณ ~500,000 บาท (รวมกล้องและเซนเซอร์)", "kpi": "ลดจำนวนครั้งแม่พิมพ์เสียหายจากการเข้าประกบผิดพลาดลง 80%, ไม่มีอุบัติเหตุจากจุดนี้", "roi": "คาดคืนทุนภายใน 10-12 เดือนจากการลดค่าซ่อมแม่พิมพ์และเวลาหยุดเครื่อง", "recommendation": "นำร่องที่เครื่อง Compression ที่มีประวัติแม่พิมพ์เสียหายบ่อยที่สุดก่อน ใช้ 2 ระบบร่วมกันคือกล้องจดจำการเคลื่อนที่ของแม่พิมพ์ (ระยะทาง/เวลา) และระบบตรวจ Pressure ที่ระยะต่างๆ", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.ส่วนผลิต Molding Plant", "output": "แจ้งเตือนอัตโนมัติ + หยุดเครื่องทันทีเมื่อพบความผิดปกติในการเข้าประกบแม่พิมพ์ พร้อมบันทึกวิดีโอ/log เหตุการณ์", "users": "พนักงานผลิตทักษะ (A,B,C,D), หัวหน้าหน่วยผลิต Molding Plant", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ทันที (< 1 วินาที)", "availability": "ตลอดเวลา 24x7 (99.9%+)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)", "refStep": "ขั้นตอนที่ 4 ผลิตและควบคุม (WI-A07-001 การ SET UP และทวนสอบกระบวนการก่อนการผลิต)", "control": "รายละเอียดที่ทำการตรวจสอบต้องผ่านทุกหัวข้อที่กำหนด", "kqi": "% GOOD RATE > 98%, % PERFORMANCE > 95%", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_2', 'หุ่นยนต์หยิบวาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่ง (Deflashing)', 'Production', '{"id": "uc_ee_2", "name": "หุ่นยนต์หยิบวาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่ง (Deflashing)", "dept": "Production", "owner": "หัวหน้าหน่วยผลิต Molding Plant", "problem": "พนักงานใช้มือวางยาง Compound เข้าแม่พิมพ์ (บางจุดใช้ Jig บางจุดไม่ใช้) และใช้มือเคลื่อนย้ายชิ้นงานจากเครื่องขึ้นรูปไปยังจุดตกแต่ง (Deflashing) ทำให้เสี่ยงบาดเจ็บจากความร้อน/แรงกด และควบคุมความสม่ำเสมอของตำแหน่งวางได้ยาก", "solution": "พนักงานวาง Compound ด้วยมือ และเดินยกชิ้นงานไปแต่งเองทุกรอบการผลิต ไม่มีระบบเคลื่อนย้ายอัตโนมัติ", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 1.2 และ 6.1 ข้อ 4.1 ตกแต่งด้วย Deflashing)", "aiType": "vision", "hardware": "แขนกล Robot Arm พร้อมกล้อง Vision-guided สำหรับหยิบจับ Compound และ Jig/Fixture เฉพาะสำหรับแต่ละรุ่นแม่พิมพ์", "impact": 4, "feasibility": 3, "data": 3, "risk": 3, "risks": "ต้องออกแบบ Layout, เส้นทางเคลื่อนที่ และอุปกรณ์จับยึดให้เหมาะกับ Compound/ชิ้นงานแต่ละรุ่น การเปลี่ยนรุ่นผลิตบ่อยอาจทำให้ต้อง Retool/Retrain บ่อย", "resources": "ทีม Automation/Robotics 2-3 คน + ทีม AI Dev 1 คน, ระยะเวลา 16 สัปดาห์, งบประมาณ ~1,200,000 บาท (รวมแขนกลและ Jig)", "kpi": "ลดอุบัติเหตุ/บาดเจ็บจากการหยิบจับที่ร้อนลง 100%, เพิ่มความสม่ำเสมอของตำแหน่งวาง Compound", "roi": "คาดคืนทุนภายใน 18-24 เดือนจากการลดของเสียจากตำแหน่งวางไม่สม่ำเสมอ และลดแรงงานจุดนี้", "recommendation": "นำร่องกับรุ่นแม่พิมพ์ที่ผลิตซ้ำปริมาณมากและ Layout คงที่ก่อน แล้วค่อยขยายไปรุ่นที่เปลี่ยนบ่อย", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.ส่วนผลิต Molding Plant", "output": "หุ่นยนต์วาง Compound เข้าแม่พิมพ์ และเคลื่อนย้ายชิ้นงานไปจุดตกแต่งโดยอัตโนมัติ ลดการใช้มือคน", "users": "พนักงานผลิตทักษะ (A,B,C,D)", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "เร็ว (1-3 วินาที)", "availability": "ตลอดเวลา 24x7 (99.9%+)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)", "refStep": "ขั้นตอนที่ 4 ผลิตและควบคุม (MOLDING WORKING STANDARD FS-R2-003)", "control": "มาตรฐานถูกต้องและอัปเดตเป็นปัจจุบัน", "kqi": "% GOOD RATE > 98%, % PERFORMANCE > 95%", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_3', 'AI จัดสรรกำลังคนตาม Skill Matrix อัตโนมัติ (AI-Driven Manpower Allocation)', 'Production', '{"id": "uc_ee_3", "name": "AI จัดสรรกำลังคนตาม Skill Matrix อัตโนมัติ (AI-Driven Manpower Allocation)", "dept": "Production", "owner": "หัวหน้างาน Molding Plant", "problem": "หัวหน้างานใช้ดุลพินิจจัดคนลงหน้างานแบบ Manual โดยอ้างอิงข้อมูลการ Fix คน Fix เครื่อง และ Part Training ที่ผูกไว้ด้วย Excel ทำให้เสี่ยงจัดพนักงานทักษะไม่ตรงกับความยากของแม่พิมพ์ จนเกิดงานเสีย (NG) และไม่มีการ Optimize ให้เกิดประสิทธิภาพสูงสุด", "solution": "หัวหน้างานจัดคนแบบ Manual จากตาราง Fix คน Fix เครื่อง, ข้อมูล Part Training, ข้อมูลการมาทำงานจาก Payroll และประวัติผลงานพนักงานรายบุคคล โดยไม่มีระบบช่วยคำนวณหรือแจ้งเตือน", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Man Alocation1/2/3 — AI-Driven Allocation Workflow)", "aiType": "recommend", "hardware": "เริ่มต้นแบบ Low-cost: Python (PuLP/SciPy.optimize/DEAP) + Google Sheets/Power Apps เป็น Dashboard ก่อน ค่อยขยับสู่ MILP + ML (XGBoost/Random Forest) บน Cloud (AWS SageMaker/Azure ML) เมื่อพร้อม", "impact": 5, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องมี Skill Matrix Database และ Job Master Data ที่ถูกต้อง ครบถ้วน และอัปเดตสม่ำเสมอ มิฉะนั้นระบบจะจัดคนผิดพลาด ต้องมี Fallback ให้หัวหน้างานปรับแก้ก่อนเริ่มงานเสมอ", "resources": "ทีม AI/Data 2 คน, ระยะเวลา 10-14 สัปดาห์ (เฟส Low-cost), งบประมาณ ~300,000-800,000 บาท ขึ้นกับระดับที่เลือก (Low-cost / Enterprise / Commercial)", "kpi": "ลด NG Rate จากพนักงานทักษะไม่ตรงงานลง, เพิ่ม % Performance worker > 95%, ลดเวลาจัดคนของหัวหน้างานต่อกะ", "roi": "คาดคืนทุนภายใน 6-9 เดือนจากการลดของเสียและเวลาที่หัวหน้างานใช้จัดคนต่อวัน", "recommendation": "เริ่มจากระดับ Low-Cost & Functional (Rule-Based + Linear Programming/Genetic Algorithm บน Python + Google Sheets/Make.com แบบ No-Code) ก่อนเป็น Quick Win แล้วค่อยพิจารณาระดับ Enterprise (MILP + ML พยากรณ์ NG Rate) เมื่อผลลัพธ์ชัดเจน", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.ส่วนผลิต Molding Plant", "output": "ตารางจัดสรรพนักงานประจำเครื่องจักร/แม่พิมพ์รายกะ พร้อมเหตุผลประกอบ ให้หัวหน้างานตรวจสอบ/ปรับแก้ก่อนเริ่มงาน", "users": "หัวหน้างาน Molding Plant, ผจก.ส่วนผลิต, HR", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ปานกลาง (3-10 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01) + ตารางบันทึกการสอนงาน FS-H2-023", "refStep": "ขั้นตอนที่ 4.9 (พนักงานที่ขึ้นปฏิบัติงานทุกคนต้องผ่านการ OJT และบันทึกผล)", "control": "พนักงานที่ขึ้นปฏิบัติงานทุกคนต้องผ่านการ OJT และบันทึกผล", "kqi": "จำนวนรายการสินค้า NC ในรอบเดือน, % PERFORMANCE WORKER > 95%", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_4', 'Auto Inspection ตรวจสอบคุณภาพชิ้นงานด้วย Machine Learning (แยกสินค้าดี/เสีย)', 'Quality Assurance', '{"id": "uc_ee_4", "name": "Auto Inspection ตรวจสอบคุณภาพชิ้นงานด้วย Machine Learning (แยกสินค้าดี/เสีย)", "dept": "Quality Assurance", "owner": "ส่วนประกันคุณภาพ (QA)", "problem": "การตรวจสอบคุณภาพชิ้นงานหลังขึ้นรูปใช้การตรวจด้วยสายตาของพนักงาน (Visual Inspection) ทำให้ผลลัพธ์ไม่คงที่ ขึ้นกับความล้าและความชำนาญของผู้ตรวจแต่ละคน และไม่มีข้อมูลภาพเก็บไว้ตรวจสอบย้อนหลัง", "solution": "พนักงาน QA เดินตรวจสอบหน้างานด้วยสายตาและวัดด้วยตัวเอง ตามใบรายงานการผลิต (ขึ้นรูปยาง) FS-F1-011", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 5.1)", "aiType": "vision", "hardware": "เครื่อง Auto Inspection พร้อมกล้อง Machine Vision + โมเดล Machine Learning สำหรับจำแนกสินค้าดี/เสีย", "impact": 4, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องเก็บภาพตัวอย่างสินค้าดีและเสียให้ครอบคลุมทุกรูปแบบตำหนิ (defect type) เพื่อเทรนโมเดลให้แม่นยำเพียงพอ และต้องมีขั้นตอนสุ่มตรวจซ้ำโดยคนในช่วงแรกเพื่อยืนยันความแม่นยำ", "resources": "ทีม AI Dev 2 คน + ทีม QA, ระยะเวลา 10 สัปดาห์, งบประมาณ ~400,000 บาท (รวมกล้องและชุดเทรนโมเดล)", "kpi": "ลดจำนวนสินค้า NC หลุดออกไปยังลูกค้าให้เป็น 0 ครั้ง/เดือน, ลดเวลาตรวจสอบต่อชิ้นลง", "roi": "คาดคืนทุนภายใน 8-10 เดือนจากการลดของเสียหลุดและลดแรงงานตรวจสอบ", "recommendation": "นำร่องกับสินค้ารุ่นที่มีประวัติของเสียซ้ำบ่อยและตำหนิสังเกตได้ชัดด้วยภาพก่อน แล้วขยายไปรุ่นอื่น", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.ส่วนประกันคุณภาพ", "output": "ผลตรวจสอบสินค้าดี/เสียแบบอัตโนมัติ พร้อมภาพหลักฐานและสถิติของเสียตามรุ่น", "users": "พนักงาน QA, ผจก.ส่วนประกันคุณภาพ", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "เร็ว (1-3 วินาที)", "availability": "ตลอดเวลา 24x7 (99.9%+)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)", "refStep": "ขั้นตอนที่ 5 (ใบรายงานการผลิต(ขึ้นรูปยาง) FS-F1-011)", "control": "เมื่อพบปัญหาของเสียหรือ Performance ให้ดำเนินการแก้ไขตามขั้นตอนปฏิบัติใน MOLDING WORKING STD.", "kqi": "% GOOD RATE > 98%, % PERFORMANCE > 95%, จำนวนครั้งที่ลูกค้า Reject 0 ครั้ง/เดือน", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_5', 'Big Data Dashboard วิเคราะห์และปิด LOT การผลิตอัตโนมัติ (Close Lot Analytics)', 'Production', '{"id": "uc_ee_5", "name": "Big Data Dashboard วิเคราะห์และปิด LOT การผลิตอัตโนมัติ (Close Lot Analytics)", "dept": "Production", "owner": "IO / ทีมวางแผนการผลิต", "problem": "การประชุม Close Lot Meeting ต้องรวบรวมข้อมูลต้นทุน, % Yield rate, % Cost, ประวัติ NC/CCR และ Last Mold/Last shot จากหลายแหล่งด้วยมือ ทำให้ใช้เวลานานและไม่สามารถประเมินกำไรของแต่ละ Lot แบบ Real-time ได้", "solution": "เจ้าหน้าที่ IO รวบรวมข้อมูลการผลิตมาคิดต้นทุนและบันทึกข้อมูลด้วยมือ แล้วนำเข้าที่ประชุม Close Lot Meeting เพื่อพิจารณาผลทีละหัวข้อ", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 9 Close Lot Meeting)", "aiType": "numeric", "hardware": "ระบบ Data Warehouse/Big Data เชื่อมข้อมูลจากหลายระบบ (ERP, MES, QA) + Dashboard วิเคราะห์ Real-time", "impact": 4, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องเชื่อมข้อมูลจากหลายระบบที่อาจมีรูปแบบไม่ตรงกัน (ERP, MES, QA, Payroll) และต้องกำหนดเจ้าของข้อมูลแต่ละส่วนให้ชัดเจนเพื่อความถูกต้องของตัวเลขต้นทุน", "resources": "ทีม Data Engineer 2 คน + ทีม IO, ระยะเวลา 12 สัปดาห์, งบประมาณ ~600,000 บาท", "kpi": "ลดเวลาที่ใช้เตรียมข้อมูลก่อนประชุม Close Lot ลง 70%, ทราบกำไร/ต้นทุนต่อ Lot แบบ Real-time", "roi": "คาดคืนทุนภายใน 12 เดือนจากเวลาที่ประหยัดได้ของทีม IO และการตัดสินใจปรับราคาที่เร็วขึ้น", "recommendation": "เริ่มเชื่อมข้อมูล % Yield rate และ % Cost ก่อนเป็นชุดแรก แล้วค่อยเพิ่มประวัติ NC/CCR และ Last Mold/Last shot", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.ส่วนผลิต Molding Plant", "output": "Dashboard สรุปผลการผลิต ต้นทุน และสถานะความพร้อมของ Mold/Tooling แบบ Real-time สำหรับที่ประชุม Close Lot", "users": "IO, ผจก.ส่วนผลิต, ทีมวางแผนการผลิต", "language": "Thai", "dataSensitivity": "ลับ (Confidential)", "latency": "ปานกลาง (3-10 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)", "refStep": "ขั้นตอนที่ 7-9 (สรุปจบแผนการผลิตและ Close Lot Meeting, WI-A07-002)", "control": "ได้มาตรการในการแก้ไขปัญหาที่เกิดขึ้นและแก้ไขเสร็จก่อน Lot ผลิตถัดไป", "kqi": "% สินค้าโอนขึ้นคลัง >98%, % งานจบตามแผน >98%, % OEE >80%", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_ee_6', 'ระบบ Barcode รับสินค้าเข้าคลังอัตโนมัติ (แทนการนับด้วยคน)', 'Warehouse', '{"id": "uc_ee_6", "name": "ระบบ Barcode รับสินค้าเข้าคลังอัตโนมัติ (แทนการนับด้วยคน)", "dept": "Warehouse", "owner": "Warehouse / คลังสินค้า", "problem": "พนักงานนำสินค้าที่บรรจุเสร็จมาส่งที่จุดพักก่อนเข้าคลัง แล้วบันทึกยอดนำส่งด้วยมือลงในใบรับโอนสินค้า จากนั้นพนักงานแพ็คต้องตรวจนับจำนวนเทียบกับตัวเลขในใบอีกครั้ง ทำให้เสี่ยงนับผิดและใช้เวลานาน", "solution": "พนักงานบันทึกยอดนำส่งด้วยมือลงในใบรับโอนสินค้า และตรวจนับจำนวนเทียบกับตัวเลขในใบด้วยสายตา", "attachRef": "ที่มา: input_data/AI_Transformation_Plan_Prod_EE.xlsx (ชีต Prod, ขั้นตอน 6.1 ข้อ 7 ส่งมอบสินค้า Out going)", "aiType": "repetitive", "hardware": "เครื่องสแกน Barcode/QR + ระบบ WMS เชื่อมกับ ERP สำหรับตัดยอด/รับเข้าคลังอัตโนมัติ", "impact": 3, "feasibility": 4, "data": 4, "risk": 1, "risks": "ต้องติดฉลาก Barcode ให้ครบทุกบรรจุภัณฑ์ตั้งแต่ต้นทาง และมีแผนสำรอง (manual) กรณีเครื่องสแกนขัดข้อง", "resources": "ทีม IT/Automation 1-2 คน, ระยะเวลา 6-8 สัปดาห์, งบประมาณ ~150,000 บาท (เครื่องสแกน + ปรับปรุงระบบ WMS)", "kpi": "ลดข้อผิดพลาดจากการนับสินค้าด้วยมือลง 90%, ลดเวลารับสินค้าเข้าคลังต่อ Lot", "roi": "คาดคืนทุนภายใน 6 เดือนจากเวลาที่ประหยัดได้และลดข้อผิดพลาดการนับ", "recommendation": "เริ่มนำร่องกับสินค้ากลุ่มที่มีปริมาณนำส่งเข้าคลังสูงสุดก่อน", "preparedBy": "ทีม AI Transformation", "approver": "ผจก.คลังสินค้า", "output": "ยอดรับสินค้าเข้าคลังที่บันทึกอัตโนมัติจากการสแกน Barcode พร้อมรายงานส่วนต่าง (ถ้ามี) แบบ Real-time", "users": "พนักงานแพ็ค, Warehouse", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ทันที (< 1 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-A07 การวางแผนและควบคุมการผลิต MOLDING (Rev.01)", "refStep": "ขั้นตอนที่ 6 (ใบรายงานการการผลิต/ส่งสินค้าเข้าคลัง FS-F1-021, WI การโอนสินค้าขึ้นคลัง)", "control": "ส่งมอบสินค้าได้ตามคุณภาพ ตามมาตรฐานที่กำหนด ไม่โดน NC", "kqi": "จำนวนครั้งที่ลูกค้า Reject 0 ครั้ง/เดือน", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_1', 'AI Agent แจ้งเตือนและสรุปเอกสาร RFQ/Drawing อัตโนมัติ', 'R&D Center', '{"id": "uc_rd_1", "name": "AI Agent แจ้งเตือนและสรุปเอกสาร RFQ/Drawing อัตโนมัติ", "dept": "R&D Center", "owner": "RD CENTER", "problem": "เมื่อฝ่ายขายส่ง RFQ พร้อม Drawing/3D Part และใบทดกลยุทธ์มาให้ RD CENTER ปัจจุบันต้องแจ้งด้วยโทรศัพท์/LINE และวิศวกรต้องอ่านเอกสารทั้งหมดเองเพื่อสรุปสาระสำคัญก่อนประเมินความสามารถในการผลิต ทำให้ล่าช้าและอาจตกหล่นรายละเอียดสำคัญใน Drawing", "solution": "SALE ส่ง RFQ + ใบทดกลยุทธ์ให้ RD CENTER ทางอีเมล/ไฟล์ แล้วโทร/แชทแจ้งให้ทราบ จากนั้นวิศวกรอ่านเอกสารเองเพื่อประเมิณความสามารถในการผลิตจากประสบการณ์", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว RFQ intake)", "aiType": "agent", "hardware": "AI Agent เชื่อมกับ WEB APPLICATION ภายในองค์กร + LLM สำหรับสรุปเอกสาร (RAG อ่าน RFQ/Drawing/3D Part)", "impact": 4, "feasibility": 4, "data": 3, "risk": 2, "risks": "Drawing/3D Part อาจอยู่หลายรูปแบบไฟล์ (PDF, CAD) ต้องมีตัวแปลง/OCR รองรับ และต้องมีคนตรวจทานสรุปของ AI ก่อนใช้งานจริงในช่วงแรกเพื่อป้องกันตีความ Drawing ผิด", "resources": "ทีม AI Dev 2 คน + ทีม IT, ระยะเวลา 8 สัปดาห์, งบประมาณ ~300,000 บาท", "kpi": "ลดเวลาตั้งแต่ได้รับ RFQ ถึงเริ่มประเมินความสามารถผลิตลง 50%, ลดจำนวนรายการ RFQ ที่ประเมินต้นทุนเกินกำหนดนัด", "roi": "คาดคืนทุนภายใน 6-8 เดือนจากเวลาที่ประหยัดได้ของวิศวกร RD และการปิดการขายที่เร็วขึ้น", "recommendation": "เริ่มจาก AI Agent แจ้งเตือนอัตโนมัติเมื่อมี RFQ ใหม่เข้า WEB APPLICATION ก่อนเป็น Quick Win แล้วต่อยอดด้วยฟีเจอร์สรุปเอกสาร RFQ/Drawing ด้วย AI", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "การแจ้งเตือน RFQ ใหม่แบบเรียลไทม์ พร้อมสรุปสาระสำคัญของ RFQ/Drawing/3D Part ให้วิศวกรอ่านก่อนตัดสินใจ", "users": "RD CENTER, SALE", "language": "Thai+Eng.", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "เร็ว (1-3 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-Axx การประเมินต้นทุนและราคาขาย Cost1", "refStep": "ขั้นตอนรับ RFQ และประเมินความสามารถในการผลิต (SALE ส่ง RFQ+ใบทดกลยุทธ์ ให้ RD CENTER)", "control": "รับเอกสาร RFQ และประเมินความสามารถในการผลิตจากประสบการณ์", "kqi": "(C) % รายการ RFQ ที่ใช้เวลาในการประเมินต้นทุนและราคาขายเกินกำหนดนัด", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_2', 'AI จับคู่ความสามารถผลิต (Feasibility Matching) และค้นหา Out Source อัตโนมัติ', 'R&D Center', '{"id": "uc_rd_2", "name": "AI จับคู่ความสามารถผลิต (Feasibility Matching) และค้นหา Out Source อัตโนมัติ", "dept": "R&D Center", "owner": "RD CENTER", "problem": "การประเมินว่าโรงงานผลิตชิ้นงานใน RFQ ได้เองหรือไม่ ต้องอาศัยประสบการณ์วิศวกรเทียบกับเอกสาร FEASIBILITY ด้วยมือ และถ้าผลิตเองไม่ได้ต้องส่งเรื่องให้ Purchase ไปค้นหา Out Source เอง ทำให้ใช้เวลานานและผลลัพธ์ไม่สม่ำเสมอ", "solution": "วิศวกรประเมินความสามารถในการผลิตจากประสบการณ์ส่วนตัว เทียบกับเอกสาร FEASIBILITY ด้วยมือ หากผลิตไม่ได้เองจะส่งข้อมูลให้ Purchase ไปหา Out Source เอง", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว FEASIBILITY / Out Source)", "aiType": "recommend", "hardware": "ระบบ AI Matching เทียบข้อมูล RFQ กับฐานข้อมูลเอกสาร FEASIBILITY + ฐานข้อมูล Out Source Supplier", "impact": 4, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องมีเอกสาร FEASIBILITY และฐานข้อมูล Out Source ที่เป็นดิจิทัลและอัปเดตสม่ำเสมอ มิฉะนั้น AI จะจับคู่ผิดพลาด ต้องมีวิศวกรยืนยันผลก่อนสรุป", "resources": "ทีม AI Dev 2 คน + ทีม Purchase, ระยะเวลา 10 สัปดาห์, งบประมาณ ~350,000 บาท", "kpi": "ลดเวลาการประเมิน Feasibility ต่อ RFQ ลง 40%, เพิ่มความแม่นยำของการตัดสินใจผลิตเอง/จ้างนอก", "roi": "คาดคืนทุนภายใน 8-10 เดือนจากเวลาที่ประหยัดได้ของวิศวกรและ Purchase", "recommendation": "เริ่มนำร่องกับกลุ่มสินค้าที่มีเอกสาร FEASIBILITY ครบถ้วนอยู่แล้วก่อน แล้วขยายฐานข้อมูลให้ครอบคลุมมากขึ้น", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "ผลประเมินความสามารถในการผลิต (ผลิตเอง/จ้างนอก) พร้อมรายชื่อ Out Source ที่เหมาะสม (ถ้าจำเป็น) ให้วิศวกรตรวจสอบ", "users": "RD CENTER, Purchase", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ปานกลาง (3-10 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-Axx การประเมินต้นทุนและราคาขาย Cost1", "refStep": "ขั้นตอนประเมินความสามารถในการผลิต (ผลิตได้เอง / ผลิตไม่ได้เอง -> ส่ง Purchase หา Out Source)", "control": "ประเมินจากประสบการณ์ เทียบกับเอกสาร FEASIBILITY", "kqi": "(A) % รายการใบเสนอราคาที่ปิดการขายแบบขายได้ ของสินค้าที่มีโอกาสเป็นสินค้ากลุ่ม A", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_3', 'AI เสนอทางเลือกกระบวนการผลิต ประเมินต้นทุน และแนะนำ Formulation (Cost1/Cost2)', 'R&D Center', '{"id": "uc_rd_3", "name": "AI เสนอทางเลือกกระบวนการผลิต ประเมินต้นทุน และแนะนำ Formulation (Cost1/Cost2)", "dept": "R&D Center", "owner": "RD CENTER (PE)", "problem": "การออกแบบกระบวนการผลิต (วิธีขึ้นรูป, จำนวน Cavity, ปริมาตร, Formulation, Cycle time ฯลฯ) และจัดทำ Cost1/Cost2 ปัจจุบันทำด้วย Excel และประสบการณ์วิศวกรล้วนๆ ทำให้ได้ทางเลือกเดียวต่อครั้ง ไม่เห็นตัวเลือกเปรียบเทียบ และ Cost1 กับ Cost2 มักคลาดเคลื่อนกันมาก (ประเมินต้นทุนผิดตั้งแต่ต้น)", "solution": "วิศวกรออกแบบกระบวนการผลิตและคัดเลือก Formulation จากประสบการณ์ จัดทำ Cost1 ด้วย Excel แบบ Manual แล้วส่งให้ Sale ทำใบเสนอราคา", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว Process Design / Cost1 / Formulation)", "aiType": "generative", "hardware": "โมเดล Generative/Optimization AI ต่อกับฐานข้อมูล Formulation, Process Design Sheet และประวัติ Cost1/Cost2 ในอดีต", "impact": 5, "feasibility": 2, "data": 3, "risk": 3, "risks": "ต้องมีข้อมูลย้อนหลังของ Process Design, Formulation และ Cost1/Cost2 จำนวนมากพอให้ AI เรียนรู้ และต้องมีวิศวกรตรวจทานทางเลือกที่ AI เสนอก่อนใช้จริงเสมอ เพราะผลกระทบต่อคุณภาพ/ต้นทุนสูง", "resources": "ทีม AI Dev 3 คน + ทีม PE, ระยะเวลา 20 สัปดาห์, งบประมาณ ~1,000,000 บาท", "kpi": "ลด (B) % Item ที่ Cost2 สูงกว่า Cost1 เกินเกณฑ์ (ประเมินต้นทุนผิด), ลดเวลาจัดทำ Cost1 ต่อรายการ", "roi": "คาดคืนทุนภายใน 12-18 เดือนจากการลดความคลาดเคลื่อนของต้นทุนและเวลาออกแบบที่ลดลง", "recommendation": "เริ่มจากการให้ AI เสนอ Formulation No. พร้อมเหตุผล (ขอบเขตแคบกว่า ข้อมูลพร้อมกว่า) ก่อนเป็น Quick Win แล้วค่อยขยายไปสู่การเสนอทางเลือกกระบวนการผลิตทั้งหมด + ประเมินต้นทุนอัตโนมัติ", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "ทางเลือกกระบวนการผลิตหลายรูปแบบ (A,B,C,D) พร้อมประเมินต้นทุนแต่ละแบบ และคำแนะนำ Formulation No. พร้อมเหตุผลประกอบ", "users": "RD CENTER (PE), SALE", "language": "Thai", "dataSensitivity": "ลับ (Confidential)", "latency": "แบบกลุ่ม/ไม่เร่งด่วน (Batch)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP-Axx การประเมินต้นทุนและราคาขาย Cost1", "refStep": "ขั้นตอนออกแบบกระบวนการผลิตและจัดทำ Cost1 (คัดเลือก Formulation, คำนวณ Cyctime, จัดทำ Cost1)", "control": "จัดทำ Cost1 (Manual Excel) ตามการออกแบบและ Formulation", "kqi": "(B) % Item Total Production Cost ของ Cost 2 > Cost 1 (Cost 1 ประเมินต้นทุนผิด)", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_4', 'AI ตรวจสอบความปลอดภัยผลิตภัณฑ์และจับคู่ QFD กับ Check Sheet (QA)', 'R&D Center', '{"id": "uc_rd_4", "name": "AI ตรวจสอบความปลอดภัยผลิตภัณฑ์และจับคู่ QFD กับ Check Sheet (QA)", "dept": "R&D Center", "owner": "QA", "problem": "หลังรับ Sample Request (SR) ฝ่าย QA ต้องวิเคราะห์ความปลอดภัยผลิตภัณฑ์ (Safety Part), กำหนดจุด SC Point และพิจารณา QFD2 ด้านการประกันคุณภาพ โดยตรวจสอบด้วยมือตาม WI และ Check List หลายชุด ทำให้ใช้เวลานานและอาจตรวจข้ามหัวข้อสำคัญ", "solution": "QA รับ SR แล้วตรวจสอบด้วยมือตาม WI โดยอ้างอิง Check List ต่างๆ เพื่อวิเคราะห์ Safety Part และ SC Point", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว QA Safety/QFD2)", "aiType": "rag", "hardware": "ระบบ RAG (ค้นหา/จับคู่เอกสาร) เชื่อมฐานข้อมูล Check Sheet, WI และข้อกำหนดความปลอดภัยผลิตภัณฑ์", "impact": 4, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องแปลง Check List/WI ให้อยู่ในรูปแบบดิจิทัลที่ AI อ่านได้ทั้งหมดก่อน และควรให้ QA ยืนยันผลการจับคู่ของ AI ทุกครั้งในช่วงแรกเพื่อความปลอดภัยของผลิตภัณฑ์", "resources": "ทีม AI Dev 2 คน + ทีม QA, ระยะเวลา 10 สัปดาห์, งบประมาณ ~350,000 บาท", "kpi": "ลด (A) %Reject สินค้าตัวอย่างสะสม, ลดเวลาตรวจสอบ Safety Part/QFD2 ต่อรายการ", "roi": "คาดคืนทุนภายใน 10-12 เดือนจากการลดของเสียจากตัวอย่างและเวลาตรวจสอบของ QA", "recommendation": "นำร่องกับกลุ่มผลิตภัณฑ์ที่มี Check List ครบถ้วนเป็นดิจิทัลอยู่แล้วก่อน", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "ผลตรวจสอบ Safety Part และการจับคู่ QFD2 กับ Check Sheet อัตโนมัติ พร้อมระบุจุด SC Point ที่ต้องเฝ้าระวัง", "users": "QA, RD CENTER", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ปานกลาง (3-10 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)", "refStep": "ขั้นตอน QA รับ SR: วิเคราะห์ Safety Part, กำหนด SC Point, พิจารณา QFD2 ด้านการประกันคุณภาพ", "control": "ตรวจสอบด้วย Manual ตาม WI โดยใช้ Check List ต่างๆ", "kqi": "(A) %Reject สินค้าตัวอย่างสะสม", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_5', 'AI Agent ติดตามสถานะแผน NPD Master Plan อัตโนมัติ', 'R&D Center', '{"id": "uc_rd_5", "name": "AI Agent ติดตามสถานะแผน NPD Master Plan อัตโนมัติ", "dept": "R&D Center", "owner": "RD CENTER", "problem": "การติดตามสถานะแผนพัฒนาผลิตภัณฑ์ใหม่ (NPD Master Plan / Project Master Plan) ปัจจุบันทำด้วยมือ (Manual) ทำให้ทราบความล่าช้าของแต่ละขั้นตอนช้า และไม่มีการแจ้งเตือนผู้เกี่ยวข้องเมื่อมีงานใกล้เกินกำหนด", "solution": "ผู้รับผิดชอบโครงการติดตามสถานะแผน NPD Master Plan ด้วยมือ (Manual) ผ่านไฟล์ Project Master Plan", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว NPD Master Plan)", "aiType": "agent", "hardware": "AI Agent เชื่อมกับไฟล์/ระบบ Project Master Plan เพื่อติดตามสถานะและแจ้งเตือนอัตโนมัติ", "impact": 4, "feasibility": 4, "data": 4, "risk": 1, "risks": "ต้องมีการอัปเดตสถานะงานในระบบสม่ำเสมอโดยผู้รับผิดชอบแต่ละขั้นตอน มิฉะนั้น AI Agent จะแจ้งเตือนผิดพลาด", "resources": "ทีม AI Dev 1-2 คน, ระยะเวลา 6 สัปดาห์, งบประมาณ ~200,000 บาท", "kpi": "ลด (C) %ในการทำตัวอย่างไม่ทันกำหนด, เพิ่ม % โครงการ NPD ที่ส่งมอบตรงตามแผน", "roi": "คาดคืนทุนภายใน 6 เดือนจากการลดความล่าช้าของโครงการ NPD", "recommendation": "เริ่มนำร่องกับโครงการ NPD ที่มีความสำคัญสูงหรือมีความเสี่ยงล่าช้าก่อน", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "การแจ้งเตือนสถานะและความคืบหน้าของแผน NPD Master Plan แบบอัตโนมัติให้ผู้เกี่ยวข้องทุกฝ่าย", "users": "RD CENTER, PE, QA", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "แบบกลุ่ม/ไม่เร่งด่วน (Batch)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)", "refStep": "ขั้นตอนจัดทำแผน NPD MASTER PLAN และติดตามสถานะ", "control": "ติดตามสถานะด้วย Manual", "kqi": "(C) %ในการทำตัวอย่างไม่ทันกำหนด", "attachment": null}');
INSERT IGNORE INTO use_cases (id, name, dept, payload) VALUES ('uc_rd_6', 'AI ช่วยคำนวณพารามิเตอร์การทดลองผลิตสินค้าตัวอย่าง (Trial Production Parameter Assistant)', 'R&D Center', '{"id": "uc_rd_6", "name": "AI ช่วยคำนวณพารามิเตอร์การทดลองผลิตสินค้าตัวอย่าง (Trial Production Parameter Assistant)", "dept": "R&D Center", "owner": "RD CENTER (PE)", "problem": "ขั้นตอนทดลอง/ผลิตสินค้าตัวอย่าง ต้องเตรียมพารามิเตอร์ (TS2/T90, Curing Time, Molding Weight, Machine Setting, ขนาด Runner และ Injection Condition) ด้วยการคำนวณ Manual จากประสบการณ์ และมักต้องผ่านกระบวนการ Trial & Error หลายรอบก่อนได้ค่าที่เหมาะสม", "solution": "วิศวกรเตรียมพารามิเตอร์ด้วยชุดเครื่องมือที่มีอยู่แบบ Manual แล้วทดลองจริง หากไม่ผ่านต้องแก้ไขปัญหาตามเครื่องมือที่มีและประสบการณ์ (Trial & Error) พร้อมบันทึกผลใน P-CAR FORM 3", "attachRef": "ที่มา: input_data/AI_Transformation_PlanRD_CENTER.xlsx (ชีต AI-Transform-Plan (RD CENTER), แถว Trial Production)", "aiType": "numeric", "hardware": "โมเดล Predictive ML (เช่น Regression/Gradient Boosting) เทรนจากประวัติผลทดลอง P-CAR FORM 3 ในอดีต เพื่อทำนายค่าพารามิเตอร์เริ่มต้นที่ใกล้เคียงค่าที่เหมาะสมที่สุด", "impact": 4, "feasibility": 3, "data": 3, "risk": 2, "risks": "ต้องมีข้อมูลผลการทดลองย้อนหลัง (P-CAR FORM 3) ที่บันทึกอย่างเป็นระบบเพียงพอสำหรับเทรนโมเดล และต้องมีวิศวกรตรวจสอบ/ปรับแต่งค่าที่ AI แนะนำก่อนใช้ทดลองจริงเสมอ", "resources": "ทีม AI Dev 2 คน + ทีม PE, ระยะเวลา 12 สัปดาห์, งบประมาณ ~450,000 บาท", "kpi": "ลดจำนวนรอบ Trial & Error ต่อผลิตภัณฑ์ใหม่ลง 30-50%, ลด (C) %ในการทำตัวอย่างไม่ทันกำหนด", "roi": "คาดคืนทุนภายใน 10-12 เดือนจากเวลาและวัตถุดิบที่ประหยัดได้จากการลดรอบ Trial & Error", "recommendation": "เริ่มเก็บข้อมูล P-CAR FORM 3 ให้เป็นดิจิทัลและเป็นระบบก่อน แล้วนำร่องโมเดลทำนายกับกลุ่มผลิตภัณฑ์ที่มีข้อมูลย้อนหลังมากที่สุด", "preparedBy": "ทีม AI Transformation", "approver": "ผจก. RD CENTER", "output": "ค่าพารามิเตอร์เริ่มต้นที่แนะนำ (Curing Time, Molding Weight, Machine Setting ฯลฯ) สำหรับการทดลองผลิตสินค้าตัวอย่างแต่ละรุ่น", "users": "RD CENTER (PE)", "language": "Thai", "dataSensitivity": "ภายในองค์กร (Internal)", "latency": "ปานกลาง (3-10 วินาที)", "availability": "เวลาทำการ 8x5 (จันทร์-ศุกร์)", "qwp": "QWP การวางแผนและผลิตสินค้าใหม่ (Advance New Product and Quality Planning)", "refStep": "ขั้นตอนทดลอง/ผลิตสินค้าตัวอย่าง (เตรียม PARAMETER, TRIAL, บันทึกผลใน P-CAR FORM 3)", "control": "เตรียม PARAMETER สำหรับทดลองด้วยชุดเครื่องมือที่มีอยู่ (Manual)", "kqi": "(C) %ในการทำตัวอย่างไม่ทันกำหนด, (A) %Reject สินค้าตัวอย่างสะสม", "attachment": null}');
